从零开始写 Agent 之九 - 浏览器自动化 来源：微信公众号「IchbinDerek」 系列：从零开始写 Agent（9/11） 链接：http://mp.weixin.qq.com/s? biz=MzA4NDI2NzgwNQ==&mid=2454801216&idx=1&sn=c5b16aa554677db6c7375630a615c026&chksm=884c2d32bf3ba4242e31af4e643002bda2cd663a5771aaa627d125c46a645a14a71c1aaa084f rd --- 《从零开始写 Agent》系列第九篇，是时候让 Agent 替我们干点活了。 说真的，现在好多工作都是在浏览器里进行的。 今天我们就来实现一个让 Agent 可以自动化操作浏览器的功能。 先看一下最终效果。 回到代码这块。 操作浏览器的工具调用的是 agent-browser 的 CLI 工具。 我觉得这个工具特别有意思。agent-browser 是 Vercel Labs 开源的，专为 AI Agent 设计的浏览器自动化 CLI 工具。 它的核心目标是，让 LLM 能以极低的 Token 成本，稳定地操作浏览器。 怎么说呢，传统的浏览器自动化工具，比如 Playwright 或者 Selenium，都太复杂了。给 Agent 用的话，Token 成本太高，而且容易出问题。 这个工具不一样，专门为 Agent 优化过。 下面是给 Agent 增加的操作浏览器工具的完整代码。 """ Browser Tools - Vercel agent-browser CLI 包装器 使用 Vercel Labs 的 agent-browser CLI (https://github.com/vercel/agent-browser) 提供浏览器自动化能力给 AI Agent 功能 - navigate to url: 访问网页 - browser click: 点击元素 - browser type: 输入文本 - browser screenshot: 截图 - browser snapshot: 获取页面快照（可访问性树） - browser eval: 执行 JavaScript - browser scroll: 滚动页面 安装依赖 npm install -g agent-browser 验证安装 agent-browser --version 参考文档 agent-browser skills get core --full """ import os import subprocess import json from typing import Optional , Dict , Any from tool decorator import tool 全局配置，CDP 连接参数 CDP PORT: Optional [ int ] = None BROWSER PROFILE: Optional [ str ] = None def set cdp connection ( port: int = 9222 , profile: str = "Default" ): global CDP PORT, BROWSER PROFILE CDP PORT = port BROWSER PROFILE = profile print ( f"✅ 已设置 CDP 连接，port= {port} , profile= {profile} " ) def run agent browser command ( args: list [ str ], timeout: int = 120 ) - tuple [ int , str , str ]: global CDP PORT, BROWSER PROFILE try : cmd = [ "agent-browser" ] if CDP PORT is not None : cmd.extend([ "--cdp" , str ( CDP PORT)]) if BROWSER PROFILE is not None : cmd.extend([ "--profile" , BROWSER PROFILE]) cmd.extend(args) result = subprocess.run( cmd, capture output= True , text= True , timeout=timeout, cwd=os.path.expanduser( " " ) ) stderr = result.stderr if stderr and "--profile ignored" in stderr: lines = stderr.split( & x27;
& x27; ) filtered lines = [l for l in lines if "--profile ignored" not in l and "daemon already running" not in l] stderr = & x27;
& x27; .join(filtered lines).strip() return result.returncode, result.stdout, stderr except subprocess.TimeoutExpired: return - 1 , "" , f"Command timed out after {timeout} s" except FileNotFoundError: return - 1 , "" , "agent-browser CLI not found. Please run npm install -g agent-browser" except Exception as e: return - 1 , "" , str (e) @tool( description= "导航到指定 URL（初始化浏览器会话）" , toolset= "browser" , safety level= "read only" , ) def navigate to url ( url: str ) - str : exit code, stdout, stderr = run agent browser command( [ "open" , url], timeout= 60 ) if exit code == 0 or "navigated" in stdout.lower(): return f"✅ 成功访问， {url} 
 {stdout[: 500 ] if stdout else & x27;页面已加载& x27; } " else : return f"❌ 访问失败， {stderr or stdout} " @tool( description= "截取当前页面屏幕截图" , toolset= "browser" , safety level= "read only" , ) def browser screenshot ( path: Optional [ str ] = None ) - str : args = [ "screenshot" , path] if path else [ "screenshot" ] exit code, stdout, stderr = run agent browser command(args, timeout= 30 ) if exit code == 0 : saved path = stdout.strip() if stdout and stdout.endswith( & x27;.png& x27; ) else path or "screen .png" return f"✅ 截图成功，保存至， {saved path} " else : return f"❌ 截图失败， {stderr or stdout} " @tool( description= "点击页面上的元素（CSS 选择器或 ref ID）" , toolset= "browser" , safety level= "interactive" , ) def browser click ( selector: str ) - str : exit code, stdout, stderr = run agent browser command( [ "click" , selector], timeout= 30 ) if exit code == 0 : return f"✅ 点击成功， {selector} 
 {stdout[: 300 ] if stdout else & x27;& x27; } " else : return f"❌ 点击失败， {stderr or stdout} " @tool( description= "在输入框中输入并填充文本" , toolset= "browser" , safety level= "interactive" , ) def browser type ( selector: str , text: str ) - str : exit code, stdout, stderr = run agent browser command( [ "fill" , selector, text], timeout= 30 ) if exit code == 0 : preview = text[: 20 ].replace( & x27;
& x27; , & x27;\n& x27; ) return f"✅ 填充成功， {preview} ， {selector} " else : return f"❌ 填充失败， {stderr or stdout} " @tool( description= "在输入框中模拟真实键盘输入（逐个字符输入，触发输入事件）" , toolset= "browser" , safety level= "interactive" , ) def browser type slow ( selector: str , text: str , delay ms: int = 50 ) - str : click exit, , click err = run agent browser command( [ "click" , selector], timeout= 10 ) if click exit != 0 : return f"❌ 点击输入框失败， {click err} " js code = f""" (function() {{ const el = document.querySelector(& x27; {selector} & x27;) document.querySelector(& x27;[node-type="textEl"]& x27;) document.querySelector(& x27;textarea& x27;) document.querySelector(& x27;[contenteditable="true"]& x27;); if (!el) return & x27;Element not found& x27;; el.focus(); el.click(); if (el.tagName === & x27;TEXTAREA& x27; or el.tagName === & x27;INPUT& x27;) {{ el.value = & x27;& x27;; }} else {{ el.innerHTML = & x27;& x27;; }} const text = & x27; {text} & x27;; for (let i = 0; i str : js code = f""" (function() {{ let el = document.querySelector(& x27;[node-type="textEl"]& x27;); if (!el) {{ el = document.querySelector(& x27;textarea[placeholder ="新鲜事"]& x27;) document.querySelector(& x27;textarea[placeholder ="分享"]& x27;) document.querySelector(& x27;[placeholder ="输入"]& x27;); }} if (!el) {{ el = document.querySelector(& x27;textarea& x27;); }} if (!el) {{ el = document.querySelector(& x27;[contenteditable="true"]& x27;) document.querySelector(& x27;.W input& x27;); }} if (!el) {{ el = document.querySelector(& x27;.send weibo .input& x27;) document.querySelector(& x27;[action-type="publish"] textarea& x27;) document.querySelector(& x27;.p input textarea& x27;); }} if (!el) {{ return & x27;ERROR: 找不到微博输入框，请检查页面是否已加载& x27;; }} el.focus(); el.click(); if (el.tagName === & x27;TEXTAREA& x27; or el.tagName === & x27;INPUT& x27;) {{ el.value = & x27;& x27;; }} else {{ el.innerHTML = & x27;& x27;; }} const inputText = & x27; {text} & x27;; for (let i = 0; i str : js code = """ (function() { let btn = document.querySelector(& x27;[node-type="submit"]& x27;); if (!btn) { btn = Array.from(document.querySelectorAll(& x27;button& x27;)).find(b = b.textContent.includes(& x27;发送& x27;) && !b.disabled ); } if (!btn) { btn = document.querySelector(& x27;.W btn a& x27;) document.querySelector(& x27;[action-type="publish"] .btn& x27;) document.querySelector(& x27;.send weibo .btn& x27;); } if (!btn) { const buttons = Array.from(document.querySelectorAll(& x27;button& x27;)); btn = buttons.find(b = { const style = window.getComputedStyle(b); const bg = style.backgroundColor; return (bg.includes(& x27;255& x27;) && bg.includes(& x27;165& x27;)) (bg.includes(& x27;255& x27;) && bg.includes(& x27;130& x27;)) b.classList.contains(& x27;W btn a& x27;) b.getAttribute(& x27;node-type& x27;) === & x27;submit& x27;; }); } if (!btn) { return & x27;ERROR: 找不到发送按钮，请确保内容已输入且页面已加载& x27;; } btn.click(); btn.dispatchEvent(new Event(& x27;click& x27;, { bubbles: true })); return & x27;SUCCESS: 已点击发送按钮& x27;; })() """ exit code, stdout, stderr = run agent browser command( [ "eval" , js code], timeout= 30 ) if exit code == 0 and & x27;SUCCESS& x27; in stdout: return "✅ 发送按钮点击成功" else : error = stderr or stdout return f"❌ 发送失败， {error} " @tool( description= "获取当前页面的可访问性树快照（带 ref 引用）" , toolset= "browser" , safety level= "read only" , ) def browser snapshot ( full: bool = False ) - str : exit code, stdout, stderr = run agent browser command( [ "snapshot" ], timeout= 30 ) if exit code == 0 : content = stdout.strip() if len (content) 3000 : return content[: 3000 ] + "

...（内容已截断，约 {} 字符）" . format ( len (content) - 3000 ) return content else : return f"❌ 获取快照失败， {stderr or stdout} " @tool( description= "在浏览器中执行 JavaScript 表达式" , toolset= "browser" , safety level= "read only" , ) def browser eval ( expression: str ) - str : exit code, stdout, stderr = run agent browser command( [ "eval" , expression], timeout= 30 ) if exit code == 0 : result = stdout.strip() try : parsed = json.loads(result) return f"✅ 执行成功，
 {json.dumps(parsed, indent= 2 , ensure ascii= False )} " except : return f"✅ 执行成功， {result[: 500 ]} " else : return f"❌ JS 执行失败， {stderr or stdout} " @tool( description= "滚动页面" , toolset= "browser" , safety level= "read only" , ) def browser scroll ( direction: str = "down" , pixels: int = 500 ) - str : valid directions = [ "up" , "down" , "left" , "right" ] if direction not in valid directions: return f"❌ 无效方向，必须是 {valid directions} 之一" args = [ "scroll" , direction] if pixels: args.append( str (pixels)) exit code, stdout, stderr = run agent browser command( args, timeout= 15 ) if exit code == 0 : return f"✅ 向 {direction} 滚动成功， {pixels} px" else : return f"❌ 滚动失败， {stderr or stdout} " @tool( description= "等待元素出现或指定时间" , toolset= "browser" , safety level= "read only" , ) def browser wait ( target: str , is ms: bool = False ) - str : exit code, stdout, stderr = run agent browser command( [ "wait" , target], timeout= 60 ) if exit code == 0 : msg = "元素已就绪" if not is ms else "等待完成" return f"✅ {msg} , {target} " else : return f"❌ 等待超时/失败， {stderr or stdout} " @tool( description= "关闭浏览器会话" , toolset= "browser" , safety level= "read only" , ) def browser close () - str : exit code, stdout, stderr = run agent browser command( [ "close" ], timeout= 15 ) if exit code == 0 : return "✅ 浏览器会话已关闭" else : return f"❌ 关闭失败， {stderr or stdout} " @tool( description= "连接到已打开的浏览器（使用 CDP）。用于共用登录态。" , toolset= "browser" , safety level= "read only" , ) def browser connect cdp ( port: int = 9222 , profile: str = "Default" ) - str : set cdp connection(port, profile) return f"✅ 已配置 CDP 连接
